import{_ as n,a0 as o,w as p,s as d,ao as g,I as t,x as e,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171018 Install a Centralized Log Server with Rsyslog in Debian 9","title":"在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器","tag":"201804","desc":""},"relativePath":"201804/20171018 Install a Centralized Log Server with Rsyslog in Debian 9.md","filePath":"[post].md"}'),c={name:"201804/20171018 Install a Centralized Log Server with Rsyslog in Debian 9.md"};function r(h,s,k,u,b,y){const i=o("Link");return p(),d("div",null,[s[13]||(s[13]=g(`<h1 id="在-debian-9-上使用-rsyslog-安裝一台中央日誌服務器" tabindex="-1">在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器 <a class="header-anchor" href="#在-debian-9-上使用-rsyslog-安裝一台中央日誌服務器" aria-label="Permalink to “在 Debian 9 上使用 Rsyslog 安裝一台中央日誌服務器”">​</a></h1><p>在 Linux 上，日誌文件包含了系統功能的信息，系統管理員經常使用日誌來確認機器上的問題所在。日誌可以幫助管理員還原在過去的時間中在系統中發生的事件。一般情況下，Linux 中所有的日誌文件都保存在 <code>/var/log</code> 目錄下。在這個目錄中，有保存着各種信息的幾種類型的日誌文件。比如，記錄系統事件的日誌文件、記錄安全相關信息的日誌文件、內核專用的日誌文件、用户或者 cron 作業使用的日誌文件。日誌文件的主要作用是系統調試。Linux 中的大部分的日誌文件都由 rsyslogd 服務來管理。在最新的 Linux 發行版中，日誌文件也可能是由 journald 系統服務來管理和控制的。journald 服務是 systemd 初始化程序的一部分。journald 以二進制的格式存儲日誌，以易失性的方式寫入到內存和 <code>/run/log/journal/</code> 中的環狀緩衝區中，但是，journald 也可以配置為永久存儲到 syslog 中。</p><p>在 Linux 中，可以配置運行一個 Rsyslog 服務器來中央化管理日誌，在流行的服務端—客户端模式中，通過 TCP 或者 UDP 傳輸協議基於網絡來發送日誌信息，或者從網絡設備、服務器、路由器、交換機、以及其它系統或嵌入式設備中接受生成的日誌。</p><p>Rsyslog 守護程序可以被同時配置為以客户端或者服務端方式運行。配置作為服務器時，Rsyslog 將缺省監聽 TCP 和 UDP 的 514 端口，來收集遠程系統基於網絡發送的日誌信息。配置為客户端運行時，Rsyslog 將通過相同的 TCP 或 UDP 端口基於網絡來發送內部日誌信息。</p><p>Rsyslog 可以根據選定的屬性和動作來過濾 syslog 信息。Rsyslog 擁有的過濾器如下：</p><ol><li>設備或者優先級過濾器</li><li>基於特性的過濾器</li><li>基於表達式的過濾器</li></ol><p>設備過濾器代表了生成日誌的 Linux 內部子系統。它們目前的分類如下：</p><ul><li><code>auth/authpriv</code> = 由驗證進程產生的信息</li><li><code>cron</code> = cron 任務相關的日誌</li><li><code>daemon</code> = 正在運行的系統服務相關的信息</li><li><code>kernel</code> = Linux 內核信息</li><li><code>mail</code> = 郵件服務器信息</li><li><code>syslog</code> = syslog 或者其它守護程序（DHCP 服務器發送的日誌在這裏）相關的信息</li><li><code>lpr</code> = 打印機或者打印服務器信息</li><li><code>local0</code> ~ <code>local7</code> = 管理員控制下的自定義信息</li></ul><p>優先級或者嚴重程度級別分配如下所述的一個關鍵字或者一個數字。</p><ul><li><code>emerg</code> = 緊急 - 0</li><li><code>alert</code> = 警報 - 1</li><li><code>err</code> = 錯誤 - 3</li><li><code>warn</code> = 警告 - 4</li><li><code>notice</code> = 提示 - 5</li><li><code>info</code> = 信息 - 6</li><li><code>debug</code> = 調試 - 7 （最高級別）</li></ul><p>此外也有一些 Rsyslog 專用的關鍵字，比如星號（<code>*</code>）可以用來定義所有的設備和優先級，<code>none</code> 關鍵字更具體地表示沒有優先級，等號（<code>=</code>）表示僅那個優先級，感嘆號（<code>!</code>）表示取消這個優先級。</p><p>Rsyslog 的動作部分由聲明的目的地來表示。日誌信息的目的地可以是：存儲在文件系統中的一個文件、 <code>/var/log/</code> 目錄下的一個文件、通過命名管道或者 FIFO 作為輸入的另一個本地進程。日誌信息也可以直達用户，或者丟棄到一個“黑洞”（<code>/dev/null</code>）中、或者發送到標準輸出、或者通過一個 TCP/UDP 協議發送到一個遠程 syslog 服務器。日誌信息也可以保存在一個數據庫中，比如 MySQL 或者 PostgreSQL。</p><h3 id="配置-rsyslog-為服務器" tabindex="-1">配置 Rsyslog 為服務器 <a class="header-anchor" href="#配置-rsyslog-為服務器" aria-label="Permalink to “配置 Rsyslog 為服務器”">​</a></h3><p>在大多數 Linux 發行版中 Rsyslog 守護程序是自動安裝的。如果你的系統中沒有安裝 Rsyslog，你可以根據你的系統發行版執行如下之一的命令去安裝這個服務。<em>運行這個命令必須有 root 權限</em>。</p><p>在基於 Debian 的發行版中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install rsyslog</span></span></code></pre></div><p>在基於 RHEL 的發行版中，比如像 CentOS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install rsyslog</span></span></code></pre></div><p>驗證 Rsyslog 守護進程是否在你的系統中運行，根據發行版不同，可以選擇運行下列的命令：</p><p>在新的使用 systemd 的 Linux 發行版中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl status rsyslog.service</span></span></code></pre></div><p>在老的使用 init 的 Linux 發行版中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service rsyslog status</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/init.d/rsyslog status</span></span></code></pre></div><p>啓動 rsyslog 守護進程運行如下的命令。</p><p>在使用 init 的老的 Linux 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service rsyslog start</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/init.d/rsyslog start</span></span></code></pre></div><p>在最新的 Linux 發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start rsyslog.service</span></span></code></pre></div><p>安裝一個 rsyslog 程序運行為服務器模式，可以編輯主要的配置文件 <code>/etc/rsyslog.conf</code> 。可以使用下列所示的命令去改變它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vi /etc/rsyslog.conf</span></span></code></pre></div><p>為了允許在 UDP 的 514 端口上接收日誌信息，找到並刪除下列行前面的井號（<code>#</code>）以取消註釋。缺省情況下，UDP 端口用於 syslog 去接收信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ModLoad imudp</span></span>
<span class="line"><span>$UDPServerRun 514</span></span></code></pre></div><p>因為在網絡上使用 UDP 協議交換數據並不可靠，你可以設置 Rsyslog 使用 TCP 協議去向遠程服務器輸出日誌信息。為了啓用 TCP 協議去接受日誌信息，打開 <code>/etc/rsyslog.conf</code> 文件並刪除如下行前面的井號（<code>#</code>）以取消註釋。這將允許 rsyslog 守護程序去綁定並監聽 TCP 協議的 514 端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ModLoad imtcp</span></span>
<span class="line"><span>$InputTCPServerRun 514</span></span></code></pre></div><p><em>在 rsyslog 上可以<strong>同時</strong>啓用兩種協議</em>。</p><p>如果你想去指定哪個發送者被允許訪問 rsyslog 守護程序，可以在啓用協議行的後面添加如下的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$AllowedSender TCP, 127.0.0.1, 10.110.50.0/24, *.yourdomain.com</span></span></code></pre></div><p>在接收入站日誌信息之前，你需要去創建一個 rsyslog 守護程序解析日誌的新模板，這個模板將指示本地 Rsyslog 服務器在哪裏保存入站的日誌信息。在 <code>$AllowedSender</code> 行後以如下示例去創建一個合適的模板。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$template Incoming-logs,&quot;/var/log/%HOSTNAME%/%PROGRAMNAME%.log&quot; </span></span>
<span class="line"><span>*.*  ?Incoming-logs</span></span>
<span class="line"><span>&amp; ~</span></span></code></pre></div><p>為了僅接收內核生成的日誌信息，可以使用如下的語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kern.*   ?Incoming-logs</span></span></code></pre></div><p>接收到的日誌由上面的模板來解析，它將保存在本地文件系統的 <code>/var/log/</code> 目錄的文件中，之後的是以客户端主機名客户端設備名命名的日誌文件名字：<code>%HOSTNAME%</code> 和 <code>%PROGRAMNAME%</code> 變量。</p><p>下面的 <code>&amp; ~</code> 重定向規則，配置 Rsyslog 守護程序去保存入站日誌信息到由上面的變量名字指定的文件中。否則，接收到的日誌信息將被進一步處理，並將保存在本地的日誌文件中，比如，<code>/var/log/syslog</code> 文件中。</p><p>為添加一個規則去丟棄所有與郵件相關的日誌信息，你可以使用下列的語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mail.* ~</span></span></code></pre></div><p>可以在輸出文件名中使用的其它變量還有：<code>%syslogseverity%</code>、<code>%syslogfacility%</code>、<code>%timegenerated%</code>、<code>%HOSTNAME%</code>、<code>%syslogtag%</code>、<code>%msg%</code>、<code>%FROMHOST-IP%</code>、<code>%PRI%</code>、<code>%MSGID%</code>、<code>%APP-NAME%</code>、<code>%TIMESTAMP%</code>、%$year%、<code>%$month%</code>、<code>%$day%</code>。</p><p>從 Rsyslog 版本 7 開始，將使用一個新的配置格式，在一個 Rsyslog 服務器中聲明一個模板。</p><p>一個版本 7 的模板應該看起來是如下行的樣子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>template(name=&quot;MyTemplate&quot; type=&quot;string&quot;</span></span>
<span class="line"><span>         string=&quot;/var/log/%FROMHOST-IP%/%PROGRAMNAME:::secpath-replace%.log&quot;</span></span>
<span class="line"><span>        )</span></span></code></pre></div><p>另一種模式是，你也可以使用如下面所示的樣子去寫上面的模板：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>template(name=&quot;MyTemplate&quot; type=&quot;list&quot;) {</span></span>
<span class="line"><span>    constant(value=&quot;/var/log/&quot;)</span></span>
<span class="line"><span>    property(name=&quot;fromhost-ip&quot;)</span></span>
<span class="line"><span>    constant(value=&quot;/&quot;)</span></span>
<span class="line"><span>    property(name=&quot;programname&quot; SecurePath=&quot;replace&quot;)</span></span>
<span class="line"><span>    constant(value=&quot;.log&quot;)</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>為了讓 Rsyslog 配置文件的變化生效，你必須重啓守護程序來加載新的配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service rsyslog restart</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart rsyslog</span></span></code></pre></div><p>在 Debian Linux 系統上去檢查它監聽哪個套接字，你可以用 root 權限去運行 <code>netstat</code> 命令。將輸出傳遞給一個過濾程序，比如 <code>grep</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netstat -tulpn | grep rsyslog</span></span></code></pre></div><p>請注意： 為了允許建立入站連接，你必須在防火牆上打開 Rsyslog 的端口。</p><p>在使用 Firewalld 的基於 RHEL 的發行版上，運行如下的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --permanent --add-port=514/tcp</span></span>
<span class="line"><span>firewall-cmd --permanent --add-port=514/tcp</span></span>
<span class="line"><span>firewall-cmd -reload</span></span></code></pre></div><p>在使用 UFW 的基於 Debian 的發行版上，運行如下的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ufw allow 514/tcp</span></span>
<span class="line"><span>ufw allow 514/udp</span></span></code></pre></div><p>Iptables 防火牆規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp -m tcp --dport 514 -j ACCEPT</span></span>
<span class="line"><span>iptables -A INPUT -p udp --dport 514 -j ACCEPT</span></span></code></pre></div><h3 id="配置-rsyslog-作為一個客户端" tabindex="-1">配置 Rsyslog 作為一個客户端 <a class="header-anchor" href="#配置-rsyslog-作為一個客户端" aria-label="Permalink to “配置 Rsyslog 作為一個客户端”">​</a></h3><p>啓用 Rsyslog 守護程序以客户端模式運行，並將輸出的本地日誌信息發送到遠程 Rsyslog 服務器，編輯 <code>/etc/rsyslog.conf</code> 文件並增加下列的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*. * @IP_REMOTE_RSYSLOG_SERVER:514</span></span>
<span class="line"><span>*. * @FQDN_RSYSLOG_SERVER:514</span></span></code></pre></div><p>這個行啓用了 Rsyslog 服務，並將輸出的所有內部日誌發送到一個遠處的 UDP 的 514 端口上運行的 Rsyslog 服務器上。</p><p>為了使用 TCP 協議去發送日誌信息，使用下列的模板：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*. *  @@IP_reomte_syslog_server:514</span></span></code></pre></div><p>輸出所有優先級的、僅與 cron 相關的日誌信息到一個 Rsyslog 服務器上，使用如下的模板：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cron.* @ IP_reomte_syslog_server:514</span></span></code></pre></div><p>在 <code>/etc/rsyslog.conf</code> 文件中添加下列行，可以在 Rsyslog 服務器無法通過網絡訪問時，臨時將客户端的日誌信息存儲在它的一個磁盤緩衝文件中，當網絡或者服務器恢復時，再次進行發送。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ActionQueueFileName queue</span></span>
<span class="line"><span>$ActionQueueMaxDiskSpace 1g</span></span>
<span class="line"><span>$ActionQueueSaveOnShutdown on</span></span>
<span class="line"><span>$ActionQueueType LinkedList</span></span>
<span class="line"><span>$ActionResumeRetryCount -1</span></span></code></pre></div><p>為使上述規則生效，需要重新 Rsyslog 守護程序，以激活為客户端模式。</p><hr>`,79)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.howtoforge.com/tutorial/rsyslog-centralized-log-server-in-debian-9/"},{default:l(()=>[...s[0]||(s[0]=[e("https://www.howtoforge.com/tutorial/rsyslog-centralized-log-server-in-debian-9/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"https://www.howtoforge.com"},{default:l(()=>[...s[2]||(s[2]=[e("Matt Vas",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),a(i,{href:"https://github.com/qhwdw"},{default:l(()=>[...s[3]||(s[3]=[e("qhwdw",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const v=n(c,[["render",r]]);export{C as __pageData,v as default};
